use std::process::ExitCode;

use wgpu::util::DeviceExt;

const WORKGROUP: u32 = 16;

const SHADER: &str = r#"
struct Dims {
    width: u32,
    height: u32,
};

@group(0) @binding(0) var<uniform> dims: Dims;
@group(0) @binding(1) var<storage, read> src: array<u32>;
@group(0) @binding(2) var<storage, read_write> dst: array<u32>;

@compute @workgroup_size(16, 16, 1)
fn main(@builtin(global_invocation_id) id: vec3<u32>) {
    let x = id.x;
    let y = id.y;
    if (x >= dims.width || y >= dims.height) {
        return;
    }
    let w = dims.width;
    let xl = select(x - 1u, x, x == 0u);
    let xr = select(x + 1u, x, x + 1u >= w);
    let yu = select(y - 1u, y, y == 0u);
    let yd = select(y + 1u, y, y + 1u >= dims.height);
    let self_v = src[y * w + x];
    let total = 4u * self_v + src[y * w + xl] + src[y * w + xr] + src[yu * w + x] + src[yd * w + x];
    dst[y * w + x] = total / 8u;
}
"#;

struct Grid {
    width: u32,
    height: u32,
    steps: u32,
    cells: Vec<u32>,
}

fn parse(text: &str) -> Result<Grid, String> {
    let mut tokens = text.split_whitespace();
    let mut next = |what: &str| -> Result<u64, String> {
        let tok = tokens
            .next()
            .ok_or_else(|| format!("unexpected end of input reading {what}"))?;
        tok.parse::<u64>()
            .map_err(|_| format!("invalid integer {tok:?} for {what}"))
    };
    let width = next("width")?;
    let height = next("height")?;
    let steps = next("steps")?;
    if !(1..=512).contains(&width) {
        return Err(format!("width {width} out of range 1..=512"));
    }
    if !(1..=512).contains(&height) {
        return Err(format!("height {height} out of range 1..=512"));
    }
    if steps > 1000 {
        return Err(format!("steps {steps} out of range 0..=1000"));
    }
    let count = (width * height) as usize;
    let mut cells = Vec::with_capacity(count);
    for i in 0..count {
        let v = next(&format!("cell {i}"))?;
        if v > 1_000_000 {
            return Err(format!("cell {i} value {v} out of range 0..=1000000"));
        }
        cells.push(v as u32);
    }
    if tokens.next().is_some() {
        return Err("unexpected extra data after the grid".to_string());
    }
    Ok(Grid {
        width: width as u32,
        height: height as u32,
        steps: steps as u32,
        cells,
    })
}

async fn run_gpu(grid: &Grid) -> Result<Vec<u32>, String> {
    let instance = wgpu::Instance::default();
    let adapter = instance
        .request_adapter(&wgpu::RequestAdapterOptions {
            power_preference: wgpu::PowerPreference::HighPerformance,
            force_fallback_adapter: false,
            compatible_surface: None,
        })
        .await
        .ok_or("no GPU adapter available")?;
    let (device, queue) = adapter
        .request_device(&wgpu::DeviceDescriptor::default(), None)
        .await
        .map_err(|e| format!("failed to open GPU device: {e}"))?;

    let shader = device.create_shader_module(wgpu::ShaderModuleDescriptor {
        label: Some("heat"),
        source: wgpu::ShaderSource::Wgsl(SHADER.into()),
    });
    let pipeline = device.create_compute_pipeline(&wgpu::ComputePipelineDescriptor {
        label: Some("heat"),
        layout: None,
        module: &shader,
        entry_point: Some("main"),
        compilation_options: Default::default(),
        cache: None,
    });

    let dims = [grid.width, grid.height, 0, 0];
    let dims_buf = device.create_buffer_init(&wgpu::util::BufferInitDescriptor {
        label: Some("dims"),
        contents: &u32s_to_bytes(&dims),
        usage: wgpu::BufferUsages::UNIFORM,
    });
    let bytes = u32s_to_bytes(&grid.cells);
    let size = bytes.len() as u64;
    let storage = wgpu::BufferUsages::STORAGE
        | wgpu::BufferUsages::COPY_SRC
        | wgpu::BufferUsages::COPY_DST;
    let bufs = [
        device.create_buffer_init(&wgpu::util::BufferInitDescriptor {
            label: Some("grid a"),
            contents: &bytes,
            usage: storage,
        }),
        device.create_buffer(&wgpu::BufferDescriptor {
            label: Some("grid b"),
            size,
            usage: storage,
            mapped_at_creation: false,
        }),
    ];
    let readback = device.create_buffer(&wgpu::BufferDescriptor {
        label: Some("readback"),
        size,
        usage: wgpu::BufferUsages::MAP_READ | wgpu::BufferUsages::COPY_DST,
        mapped_at_creation: false,
    });

    let layout = pipeline.get_bind_group_layout(0);
    let bind_groups: Vec<wgpu::BindGroup> = (0..2)
        .map(|i| {
            device.create_bind_group(&wgpu::BindGroupDescriptor {
                label: None,
                layout: &layout,
                entries: &[
                    wgpu::BindGroupEntry {
                        binding: 0,
                        resource: dims_buf.as_entire_binding(),
                    },
                    wgpu::BindGroupEntry {
                        binding: 1,
                        resource: bufs[i].as_entire_binding(),
                    },
                    wgpu::BindGroupEntry {
                        binding: 2,
                        resource: bufs[1 - i].as_entire_binding(),
                    },
                ],
            })
        })
        .collect();

    let groups_x = grid.width.div_ceil(WORKGROUP);
    let groups_y = grid.height.div_ceil(WORKGROUP);
    // Submit in batches so a single command buffer never grows too large.
    const BATCH: u32 = 100;
    let mut done = 0;
    while done < grid.steps {
        let n = BATCH.min(grid.steps - done);
        let mut encoder = device.create_command_encoder(&Default::default());
        for s in done..done + n {
            // Each pass is a separate dispatch; wgpu inserts the barrier that
            // makes one step's writes visible to the next step's reads.
            let mut pass = encoder.begin_compute_pass(&Default::default());
            pass.set_pipeline(&pipeline);
            pass.set_bind_group(0, &bind_groups[(s % 2) as usize], &[]);
            pass.dispatch_workgroups(groups_x, groups_y, 1);
        }
        queue.submit(Some(encoder.finish()));
        done += n;
    }

    let result = &bufs[(grid.steps % 2) as usize];
    let mut encoder = device.create_command_encoder(&Default::default());
    encoder.copy_buffer_to_buffer(result, 0, &readback, 0, size);
    queue.submit(Some(encoder.finish()));

    let slice = readback.slice(..);
    let (tx, rx) = std::sync::mpsc::channel();
    slice.map_async(wgpu::MapMode::Read, move |r| {
        let _ = tx.send(r);
    });
    device.poll(wgpu::Maintain::Wait);
    rx.recv()
        .map_err(|_| "GPU readback was dropped")?
        .map_err(|e| format!("failed to map readback buffer: {e}"))?;
    let data = slice.get_mapped_range();
    let out = data
        .chunks_exact(4)
        .map(|c| u32::from_le_bytes([c[0], c[1], c[2], c[3]]))
        .collect();
    drop(data);
    readback.unmap();
    Ok(out)
}

fn u32s_to_bytes(v: &[u32]) -> Vec<u8> {
    v.iter().flat_map(|x| x.to_le_bytes()).collect()
}

fn main() -> ExitCode {
    let Some(path) = std::env::args().nth(1) else {
        eprintln!("usage: gpu-heat <input-file>");
        return ExitCode::from(2);
    };
    let text = match std::fs::read_to_string(&path) {
        Ok(t) => t,
        Err(e) => {
            eprintln!("cannot read {path}: {e}");
            return ExitCode::FAILURE;
        }
    };
    let grid = match parse(&text) {
        Ok(g) => g,
        Err(e) => {
            eprintln!("invalid input: {e}");
            return ExitCode::FAILURE;
        }
    };
    let cells = match pollster::block_on(run_gpu(&grid)) {
        Ok(c) => c,
        Err(e) => {
            eprintln!("GPU error: {e}");
            return ExitCode::FAILURE;
        }
    };

    let mut out = String::with_capacity(cells.len() * 8);
    let mut sum: u64 = 0;
    for row in cells.chunks(grid.width as usize) {
        for (i, v) in row.iter().enumerate() {
            if i > 0 {
                out.push(' ');
            }
            out.push_str(&v.to_string());
            sum += u64::from(*v);
        }
        out.push('\n');
    }
    out.push_str(&format!("SUM {sum}\n"));
    use std::io::Write;
    let mut stdout = std::io::stdout().lock();
    if stdout.write_all(out.as_bytes()).and_then(|_| stdout.flush()).is_err() {
        return ExitCode::FAILURE;
    }
    ExitCode::SUCCESS
}
